import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"學易筆談序","description":"杭氏易學 - 學易筆談序","frontmatter":{"title":"學易筆談序","description":"杭氏易學 - 學易筆談序"},"headers":[],"relativePath":"classics/hangshi/020.md","filePath":"classics/hangshi/020.md"}'),i={name:"classics/hangshi/020.md"};function c(o,a,l,d,p,h){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"學易筆談序",tabindex:"-1"},[n("學易筆談序 "),e("a",{class:"header-anchor",href:"#學易筆談序","aria-label":"Permalink to “學易筆談序”"},"​")],-1),e("p",null,"海寧先生之於《易》，得異人傳授，又博極諸家傳注，故能竟委窮源，而獨見其大。先生於書，無所不讀，故能探賾索隱，鉤貫於新舊之學，而獨得其通。昔嘗聞之先生曰：《易》始於包犧氏，備於神農、黃帝，大明於文王、周公、孔子。漢人去古未遠，其卦氣、飛伏、陰陽、消息，皆有所授受，非能自創。孔子贊《易》，專重人道，以明立教之旨。故三陳九德，以人合天，而筮法僅略言及之。朱子乃謂“《易》為聖人教人卜筮之書”，豈知方耶？然河、洛為《易》象所取則，漢學只詆為偽造，朱子獨取以冠經首，是其卓識，亦有不可及者。又曰：“道家祖黃老，淵源悉出於《易》。”其七返九還，六歸八居，度數與卦象悉合無論矣。所異者佛產印度，耶穌生於猶太，而《華嚴》之乘數，《金剛》之相數，一八、三六、百零八之數，及“七日來複”、“十三見兇之數”，亦無不得。僅以素所聞於先生者，弁諸簡端，並志其緣起如此雲。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
